    labels=key.encode('ascii').split(b'.')
    if any(not 1<=len(label)<=63 for label in labels):raise ValueError('invalid name')
    wire=b''.join(bytes([len(label)])+label for label in labels)+b'\0'
    if len(wire)>255:raise ValueError('invalid name')
    xid=secrets.randbelow(65536);query=struct.pack('!HHHHHH',xid,0x100,1,0,0,0)+wire+b'\0\1\0\1'
    with socket.socket(socket.AF_INET,socket.SOCK_DGRAM) as sock:sock.settimeout(2);sock.connect((host,port));sock.send(query);data=sock.recv(65535)
    if len(data)<len(query) or data[:2]!=query[:2] or data[12:len(query)]!=query[12:]:raise ValueError('invalid reply')
    flags,qd,an,ns,ar=struct.unpack('!HHHHH',data[2:12]);rcode=flags&15
    if not flags&0x8000 or flags&0x200 or qd!=1 or rcode not in (0,3) or ar:raise ValueError('DNS failure')
    def name_end(pos):
